import * as passwordInputMachine from "@zag-js/password-input";
import type { MachineInput } from "marko-zag";
import Icon from "../icon/icon.marko";
import { cn } from "../../../lib/utils.ts";
import { stripOwnProps } from "../../../lib/native-attrs.ts";

export type Input = MachineInput<"input", passwordInputMachine.Props> & {
  visibleChange?: (visible: boolean) => void;
  label?: string;
};

<machine-props/machineProps from=input pick=passwordInputMachine.props
  onVisibilityChange(details: passwordInputMachine.VisibilityChangeDetails) {
    input.onVisibilityChange?.(details);
    input.visibleChange?.(details.visible);
  }/>
<service/service machine=() => passwordInputMachine.machine props=machineProps/>
<connect/api=(service, normalizeProps) =>
  passwordInputMachine.connect(service, normalizeProps)
  service=service
/>

<const/nativeAttrs=() =>
  stripOwnProps(
    passwordInputMachine.splitProps(input)[1],
    "class",
    "visibleChange",
    "label",
  )
>

<div ...api().getRootProps() data-slot="password-input-root" class="grid w-full gap-1.5">
  <if=input.label>
    <label ...api().getLabelProps() data-slot="password-input-label" class="text-sm leading-none font-medium select-none">
      ${input.label}
    </label>
  </if>
  <div ...api().getControlProps() data-slot="password-input-control" class="relative flex items-center">
    <input
      ...nativeAttrs()
      ...api().getInputProps()
      data-slot="password-input"
      class=cn(
        "file:text-foreground placeholder:text-muted-foreground selection:bg-primary selection:text-primary-foreground dark:bg-input/30 border-input flex h-9 w-full min-w-0 rounded-md border bg-transparent px-3 py-1 pr-9 text-base shadow-xs transition-[color,box-shadow] outline-none file:inline-flex file:h-7 file:border-0 file:bg-transparent file:text-sm file:font-medium disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 md:text-sm",
        "focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px]",
        "aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
        input.class,
      )
    />
    <button
      ...api().getVisibilityTriggerProps()
      data-slot="password-input-visibility-trigger"
      class="text-muted-foreground hover:text-foreground absolute right-0 inline-flex size-9 shrink-0 items-center justify-center rounded-md outline-none transition-colors focus-visible:ring-ring/50 focus-visible:ring-[3px] disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0"
    >
      <span ...api().getIndicatorProps() data-slot="password-input-indicator">
        // Sizing stays on the parent button's `[&_svg]:size-4`, matching the
        // markup these two replaced (bare <svg>, no class of its own) —
        // <Icon>'s own default `size-4` agrees with it either way.
        <if=api().visible>
          <Icon name="EyeOffIcon"/>
        </if>
        <else>
          <Icon name="EyeIcon"/>
        </else>
      </span>
      <span class="sr-only">${api().visible ? "Hide password" : "Show password"}</span>
    </button>
  </div>
</div>

<return=api>
